// Bundled exam practice questions (SAT, GMAT, CAT and shared aptitude and English words).
// Written for Quirzy. Answers and explanations are checked by tests; add new questions at the END of a
// topic so existing question ids stay the same.

/// One bundled question. [exams] is a space-separated list of exam ids.
class BankQuestion {
  final String topic;
  final String exams;
  final String text;
  final List<String> options;
  final int correct;
  final String explanation;

  const BankQuestion(this.topic, this.exams, this.text, this.options, this.correct, this.explanation);

  Set<String> get examIds => exams.split(' ').toSet();
}

