  BankQuestion('Arithmetic', 'sat gmat cat gre', 'What is the compound interest on \$10,000 at 10% per year for 2 years?', ['\$2,200', '\$2,000', '\$1,900', '\$2,100'], 3, '10,000 × 1.1² = 12,100, so the interest is 2,100.'),
  BankQuestion('Arithmetic', 'sat gmat cat gre', 'A car travels 120 km at 40 km/h and returns at 60 km/h. What is its average speed for the whole trip?', ['50 km/h', '45 km/h', '52 km/h', '48 km/h'], 3, 'Total distance 240 km; time 3 + 2 = 5 hours; 240 ÷ 5 = 48 km/h.'),
  BankQuestion('Arithmetic', 'sat gmat cat gre', 'A can finish a job in 12 days and B in 18 days. Working together, how many days do they need?', ['7.2', '6', '8', '7.5'], 0, 'Combined rate 1/12 + 1/18 = 5/36 per day, so 36/5 = 7.2 days.'),
  BankQuestion('Arithmetic', 'sat gmat cat gre', 'One pipe fills a tank in 6 hours and another empties it in 12 hours. With both open, how long to fill the tank?', ['18 hours', '12 hours', '9 hours', '6 hours'], 1, 'Net rate 1/6 − 1/12 = 1/12 per hour, so 12 hours.'),
  BankQuestion('Arithmetic', 'sat gmat cat gre', 'A 150 m train passes a pole in 10 seconds. What is its speed?', ['36 km/h', '60 km/h', '54 km/h', '45 km/h'], 2, '150 ÷ 10 = 15 m/s, and 15 × 3.6 = 54 km/h.'),
  BankQuestion('Arithmetic', 'sat gmat cat gre', 'Two trains 300 km apart move towards each other at 70 km/h and 80 km/h. After how many hours do they meet?', ['2.5', '1.5', '3', '2'], 3, 'Closing speed 150 km/h, so 300 ÷ 150 = 2 hours.'),
  BankQuestion('Arithmetic', 'sat gmat cat gre', '8 workers finish a task in 15 days. How many days would 12 workers need?', ['22', '12', '18', '10'], 3, 'Total work is 8 × 15 = 120 worker-days; 120 ÷ 12 = 10.'),
  BankQuestion('Arithmetic', 'sat gmat cat gre', 'A boat goes 12 km/h in still water and the stream flows at 3 km/h. How long to go 45 km downstream?', ['4 hours', '3.75 hours', '5 hours', '3 hours'], 3, 'Downstream speed 15 km/h; 45 ÷ 15 = 3 hours.'),
  BankQuestion('Number Systems', 'gmat cat', 'What is the remainder when 2¹⁰ is divided by 7?', ['2', '4', '1', '3'], 0, '2³ = 8 leaves remainder 1, so 2⁹ leaves 1 and 2¹⁰ leaves 2.'),
  BankQuestion('Number Systems', 'gmat cat', 'What is the LCM of 12, 18 and 30?', ['120', '180', '360', '90'], 1, '12 = 2²·3, 18 = 2·3², 30 = 2·3·5; the LCM is 2²·3²·5 = 180.'),
  BankQuestion('Number Systems', 'gmat cat', 'What is the HCF of 84 and 126?', ['12', '28', '21', '42'], 3, '84 = 2²·3·7 and 126 = 2·3²·7; the common part is 2·3·7 = 42.'),
  BankQuestion('Number Systems', 'gmat cat', 'How many positive divisors does 36 have?', ['12', '10', '8', '9'], 3, '36 = 2²·3², so (2 + 1)(2 + 1) = 9 divisors.'),
  BankQuestion('Number Systems', 'gmat cat', 'What is the units digit of 7²³?', ['7', '9', '1', '3'], 3, 'Units digits of powers of 7 repeat 7, 9, 3, 1. 23 leaves remainder 3 when divided by 4, so the digit is 3.'),
  BankQuestion('Number Systems', 'gmat cat', 'What is the sum of the first 20 positive even numbers?', ['420', '400', '210', '440'], 0, 'The sum is 2(1 + 2 + … + 20) = 2 × 210 = 420.'),
  BankQuestion('Number Systems', 'gmat cat', 'How many prime numbers are there between 20 and 40?', ['3', '6', '4', '5'], 2, 'The primes are 23, 29, 31 and 37.'),
  BankQuestion('Geometry', 'sat gmat cat', 'A rectangle is 12 long and 5 wide. What is the length of its diagonal?', ['13', '14', '17', '15'], 0, '√(12² + 5²) = √169 = 13.'),
  BankQuestion('Geometry', 'sat gmat cat', 'A circle has diameter 14. What is its area?', ['196π', '14π', '28π', '49π'], 3, 'Radius 7, so the area is π × 7² = 49π.'),
  BankQuestion('Geometry', 'sat gmat cat', 'Two angles of a triangle are 50° and 60°. What is the third?', ['130°', '60°', '70°', '80°'], 2, 'Angles sum to 180°, so 180 − 110 = 70°.'),
  BankQuestion('Geometry', 'sat gmat cat', 'A right triangle has legs 9 and 12. What is its hypotenuse?', ['13', '21', '14', '15'], 3, '√(81 + 144) = √225 = 15.'),
  BankQuestion('Geometry', 'sat gmat cat', 'What is each interior angle of a regular hexagon?', ['120°', '135°', '108°', '150°'], 0, 'Interior angles sum to (6 − 2) × 180 = 720°, so each is 120°.'),
  BankQuestion('Geometry', 'sat gmat cat', 'A cylinder has radius 3 and height 5. What is its volume?', ['15π', '30π', '45π', '90π'], 2, 'V = πr²h = π × 9 × 5 = 45π.'),
  BankQuestion('Geometry', 'sat gmat cat', 'What is the area of an equilateral triangle with side 6?', ['12√3', '18√3', '9', '9√3'], 3, 'Area = (√3/4) × 6² = 9√3.'),
  BankQuestion('Data Interpretation', 'sat gmat cat gre', 'Monthly sales (units): Jan 120, Feb 150, Mar 135, Apr 180.\n\nWhich month-to-month change was the largest increase?', ['There was no increase', 'January to February (+30)', 'March to April (+45)', 'February to March (+15)'], 2, 'Changes: +30, −15, +45. The largest increase is March to April.'),
  BankQuestion('Data Interpretation', 'sat gmat cat gre', 'Monthly sales (units): Jan 120, Feb 150, Mar 135, Apr 180.\n\nWhat is the average monthly sales?', ['140', '150', '135', '146.25'], 3, 'Total 585 ÷ 4 = 146.25.'),
