  BankQuestion('Data Interpretation', 'sat gmat cat gre', 'Goals scored: Team A 45, Team B 60, Team C 30.\n\nWhat share of all goals did Team B score?', ['44.4%', '33.3%', '50%', '40%'], 0, 'The total is 135; 60 ÷ 135 ≈ 0.444.'),
  BankQuestion('Data Sufficiency', 'gmat', 'Is x > 0?\n(1) x² = 9\n(2) x + 3 > 0', ['Only (1) is sufficient', 'Only (2) is sufficient', 'Both together, but neither alone', 'Each one is sufficient alone', 'Not sufficient, even together'], 2, '(1) gives x = 3 or -3: not enough. (2) gives x > -3: not enough. Together x = 3, so x > 0. Answer: both together.'),
  BankQuestion('Data Sufficiency', 'gmat', 'What is the value of y?\n(1) 2y + 6 = 14\n(2) y² = 16', ['Only (1) is sufficient', 'Only (2) is sufficient', 'Both together, but neither alone', 'Each one is sufficient alone', 'Not sufficient, even together'], 0, '(1) gives y = 4, sufficient. (2) gives y = 4 or -4, not sufficient. Answer: (1) alone.'),
  BankQuestion('Data Sufficiency', 'gmat', 'Is the integer n even?\n(1) n² is even\n(2) n + 1 is odd', ['Only (1) is sufficient', 'Only (2) is sufficient', 'Both together, but neither alone', 'Each one is sufficient alone', 'Not sufficient, even together'], 3, '(1) If n² is even, n is even. (2) If n + 1 is odd, n is even. Each statement alone is sufficient.'),
  BankQuestion('Data Sufficiency', 'gmat', 'What is the average of a and b?\n(1) a − b = 4\n(2) a + b = 20', ['Only (1) is sufficient', 'Only (2) is sufficient', 'Both together, but neither alone', 'Each one is sufficient alone', 'Not sufficient, even together'], 1, 'The average is (a + b)/2. (1) says nothing about the sum. (2) gives the sum 20, so the average is 10. Answer: (2) alone.'),
  BankQuestion('Data Sufficiency', 'gmat', 'What is the area of a rectangle?\n(1) Its perimeter is 20.\n(2) Its length is 6.', ['Only (1) is sufficient', 'Only (2) is sufficient', 'Both together, but neither alone', 'Each one is sufficient alone', 'Not sufficient, even together'], 2, '(1) alone allows many shapes. (2) alone gives no width. Together: 2(6 + w) = 20 so w = 4 and area = 24.'),
  BankQuestion('Data Sufficiency', 'gmat', 'If x and y are integers, is xy even?\n(1) x is even\n(2) y is odd', ['Only (1) is sufficient', 'Only (2) is sufficient', 'Both together, but neither alone', 'Each one is sufficient alone', 'Not sufficient, even together'], 0, '(1) An even factor makes the product even: sufficient. (2) With y odd, xy is even only if x is even: not sufficient.'),
  BankQuestion('Data Sufficiency', 'gmat', 'What is the price of one pen?\n(1) 3 pens and 2 notebooks cost \$12.\n(2) 6 pens and 4 notebooks cost \$24.', ['Only (1) is sufficient', 'Only (2) is sufficient', 'Both together, but neither alone', 'Each one is sufficient alone', 'Not sufficient, even together'], 4, '(2) is just (1) doubled, so it adds no new information. Two unknowns, one equation: not sufficient even together.'),
  BankQuestion('Data Sufficiency', 'gmat', 'In triangle PQR, is angle P a right angle?\n(1) PQ = PR\n(2) PQ² + PR² = QR²', ['Only (1) is sufficient', 'Only (2) is sufficient', 'Both together, but neither alone', 'Each one is sufficient alone', 'Not sufficient, even together'], 1, '(1) only says the triangle is isosceles. (2) is the converse of the Pythagorean theorem: the angle opposite QR, angle P, is 90°. Answer: (2) alone.'),
